import java.util.*;

class SQL {
    private final Map<String, String> cells = new HashMap<>();
    private final Map<String, Integer> nextRowId = new HashMap<>();
    private final Map<String, Integer> columnsByName = new HashMap<>();

    public SQL(List<String> names, List<Integer> columns) {
        for (int i = 0; i < names.size(); i++) {
            nextRowId.put(names.get(i), 1);
            columnsByName.put(names.get(i), columns.get(i));
        }
    }

    public void insertRow(String name, List<String> row) {
        int rowId = nextRowId.get(name);
        nextRowId.put(name, rowId + 1);
        for (int column = 0; column < row.size(); column++) {
            cells.put(key(name, rowId, column + 1), row.get(column));
        }
    }

    public void deleteRow(String name, int rowId) {
        for (int column = 1; column <= columnsByName.get(name); column++) {
            cells.remove(key(name, rowId, column));
        }
    }

    public String selectCell(String name, int rowId, int columnId) {
        return cells.get(key(name, rowId, columnId));
    }

    private String key(String name, int rowId, int columnId) {
        return name + "#" + rowId + "#" + columnId;
    }
}

import java.util.*;

class SQL {
    private final Map<String, Map<Integer, String[]>> rowsByTable = new HashMap<>();
    private final Map<String, Integer> nextRowId = new HashMap<>();

    public SQL(List<String> names, List<Integer> columns) {
        for (String name : names) {
            rowsByTable.put(name, new HashMap<>());
            nextRowId.put(name, 1);
        }
    }

    public void insertRow(String name, List<String> row) {
        int rowId = nextRowId.get(name);
        nextRowId.put(name, rowId + 1);
        rowsByTable.get(name).put(rowId, row.toArray(new String[0]));
    }

    public void deleteRow(String name, int rowId) {
        rowsByTable.get(name).remove(rowId);
    }

    public String selectCell(String name, int rowId, int columnId) {
        return rowsByTable.get(name).get(rowId)[columnId - 1];
    }
}

import java.util.*;

class SQL {
    private final Map<String, Table> tables = new HashMap<>();

    public SQL(List<String> names, List<Integer> columns) {
        for (int i = 0; i < names.size(); i++) {
            tables.put(names.get(i), new Table(columns.get(i)));
        }
    }

    public void insertRow(String name, List<String> row) {
        tables.get(name).insert(row);
    }

    public void deleteRow(String name, int rowId) {
        tables.get(name).delete(rowId);
    }

    public String selectCell(String name, int rowId, int columnId) {
        return tables.get(name).select(rowId, columnId);
    }

    private static class Table {
        private int nextRowId = 1;
        private final List<Map<Integer, String>> columns = new ArrayList<>();

        Table(int columnCount) {
            for (int i = 0; i < columnCount; i++) {
                columns.add(new HashMap<>());
            }
        }

        void insert(List<String> row) {
            int rowId = nextRowId++;
            for (int column = 0; column < row.size(); column++) {
                columns.get(column).put(rowId, row.get(column));
            }
        }

        void delete(int rowId) {
            for (Map<Integer, String> column : columns) {
                column.remove(rowId);
            }
        }

        String select(int rowId, int columnId) {
            return columns.get(columnId - 1).get(rowId);
        }
    }
}
